      "As principais características, muito cobradas em prova: universalidade (valem para todo ser humano, sem distinção), historicidade (surgem e se transformam ao longo da história, não são estáticos), indivisibilidade (não podem ser separados uns dos outros — direitos civis, políticos, sociais e econômicos formam um conjunto único e interdependente), interdependência (a realização de um direito favorece a realização dos demais, e a violação de um afeta os outros).",
      "Além dessas, destacam-se: imprescritibilidade (não se perdem pelo decurso do tempo), irrenunciabilidade (a pessoa não pode abrir mão deles, mesmo que queira), e vedação ao retrocesso (uma vez consolidado um patamar de proteção, não se admite retroceder a um nível de proteção inferior, sem justificativa robusta)."
