    "corpo": [
      "A Declaração Universal dos Direitos Humanos (1948), adotada pela Assembleia Geral da ONU logo após a Segunda Guerra Mundial, é o documento fundador do sistema internacional de proteção — não tem força de tratado vinculante em sentido estrito (é uma resolução, uma declaração de princípios), mas seu conteúdo é amplamente reconhecido como refletindo costume internacional e serve de base para praticamente todos os tratados posteriores.",
      "Para dar força jurídica vinculante aos princípios da Declaração, foram adotados dois pactos internacionais em 1966: o Pacto Internacional dos Direitos Civis e Políticos (que trata da primeira geração — vida, liberdade, devido processo) e o Pacto Internacional dos Direitos Econômicos, Sociais e Culturais (segunda geração — trabalho, educação, saúde). Juntos com a Declaração, formam a chamada 'Carta Internacional dos Direitos Humanos'.",
      "No plano brasileiro, os tratados de direitos humanos aprovados pelo Congresso Nacional, em dois turnos, por três quintos dos votos em cada Casa, equivalem a emendas constitucionais (art. 5º, §3º, da CF, incluído pela EC 45/2004) — os demais tratados de direitos humanos, aprovados pelo rito comum, têm status supralegal (abaixo da Constituição, mas acima da lei ordinária), conforme entendimento consolidado do STF."
    ],
