    "corpo": [
      "A busca pessoal — revista de alguém e de seus pertences — é medida cautelar que restringe a intimidade e a liberdade individual, e por isso exige um requisito objetivo: fundada suspeita de que a pessoa oculta consigo arma proibida ou objetos ou papéis que constituam corpo de delito (art. 244 do CPP). Fundada suspeita não pode se basear em critérios subjetivos vagos como aparência, cor da pele, forma de vestir ou local de moradia — precisa estar ancorada em elementos objetivos e articuláveis da situação concreta.",
      "A jurisprudência mais recente do STJ tem exigido que a autoridade policial consiga expor, de forma objetiva e verificável a posteriori, os elementos concretos que fundamentaram a suspeita (comportamento evasivo específico, correspondência com características de suspeito já identificado em investigação, atitude de fuga ao avistar a viatura, entre outros) — a mera alegação genérica de 'atitude suspeita' ou enquadramento em perfil (por raça, idade, vestimenta ou território) não basta e pode configurar abordagem discriminatória e ilegal, com nulidade das provas obtidas.",
      "Essa exigência de fundamentação concreta busca equilibrar dois valores: a efetividade da atividade policial preventiva (que precisa de alguma margem de avaliação em campo) e a proteção contra abordagens arbitrárias, que historicamente atingem de forma desproporcional determinados grupos sociais e raciais — um dos temas mais sensíveis e recorrentes em avaliação de direitos humanos aplicados à atividade policial."
    ],
