        "respostaEsperada": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Abordagem policial e busca pessoal\", a ideia principal é: A busca pessoal — revista de alguém e de seus pertences — é medida cautelar que restringe a intimidade e a liberdade individual, e por isso exige um requisito objetivo: fundada suspeita de que a pessoa oculta consigo arma proibida ou objetos ou papéis que constituam corpo de delito (art. Para estudar sem travar, guarde primeiro estas palavras-chave: fundada suspeita, busca pessoal, abordagem discriminatória. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Fundada suspeita exige elemento concreto e articulável — nunca raça, vestimenta ou território isoladamente, e o resultado da busca não legitima abordagem irregular.",
