    "corpo": [
      "A privação de liberdade não suprime a condição de sujeito de direitos da pessoa presa — a Constituição garante expressamente que é assegurado aos presos o respeito à integridade física e moral (art. 5º, XLIX), e que a pena não passará da pessoa do condenado (art. 5º, XLV), entre outras garantias específicas. As Regras Mínimas das Nações Unidas para o Tratamento de Reclusos (Regras de Mandela, revisadas em 2015) estabelecem padrões internacionais mínimos: separação de presos por categoria (sexo, idade, situação processual), condições adequadas de higiene, alimentação e assistência à saúde, vedação a castigos corporais e a qualquer forma de tortura ou tratamento cruel, desumano ou degradante.",
      "O Supremo Tribunal Federal, no julgamento da ADPF 347, reconheceu formalmente que o sistema penitenciário brasileiro vive um 'estado de coisas inconstitucional' — quando um quadro de violação massiva, generalizada e persistente de direitos fundamentais, decorrente de falhas estruturais e falta de coordenação entre os Poderes, exige a atuação do Judiciário para determinar políticas públicas voltadas à superação dessa situação (superlotação, condições degradantes, violência entre presos).",
      "As Regras de Bangkok (2010) complementam as Regras de Mandela com foco específico nas necessidades de mulheres presas: previsão de acompanhamento pré-natal e pós-parto adequado, atenção a filhos que acompanham a mãe no cárcere (nos primeiros anos de vida), vedação a algemas durante o parto e revistas íntimas degradantes, entre outras garantias específicas de gênero no ambiente prisional."
    ],
