    "corpo": [
      "A Política Nacional para a População em Situação de Rua (instituída por decreto federal) reconhece essa população como grupo com direitos plenos, vedando qualquer abordagem que trate a situação de rua, por si só, como infração ou indício de conduta criminosa — a mera condição de estar em situação de rua não autoriza abordagem, revista ou remoção compulsória, que dependem sempre de fundamento jurídico próprio (relembre o conceito de fundada suspeita, visto anteriormente).",
      "Pessoas transgênero e travestis têm reconhecido, por resoluções e diretrizes específicas (inclusive do Conselho Nacional de Justiça e de órgãos de segurança pública), o direito ao uso do nome social em qualquer registro ou tratamento oficial, correspondente à identidade de gênero, independentemente de alteração de registro civil — o desrespeito a esse direito durante abordagem, condução ou custódia pode configurar violação de direitos humanos e, a depender do contexto, discriminação ilegal.",
      "Povos e comunidades tradicionais (indígenas, quilombolas, ribeirinhos, entre outros) têm proteção constitucional específica de seus territórios, cultura e modo de vida (arts. 215, 216 e 231 da CF) — a atuação policial em territórios tradicionais exige observância de protocolos específicos de abordagem que respeitem a organização social, os costumes e, quando aplicável, a necessidade de acompanhamento por órgãos especializados (como a FUNAI, em terras indígenas) para mediar a comunicação e evitar violação de direitos culturais."
    ],
